sealed class SoftifyException: kotlin.Exception() {
    
    class Network(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class NotFound(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Decryption(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Database(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class QualityVerification(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class ProviderUnavailable(
        
        val `provider`: kotlin.String, 
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "provider=${ `provider` }, reason=${ `reason` }"
    }
    
    class Download(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Import(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Scan(
        
        val `reason`: kotlin.String
        ) : SoftifyException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SoftifyException> {
        override fun lift(error_buf: RustBuffer.ByValue): SoftifyException = FfiConverterTypeSoftifyError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSoftifyError : FfiConverterRustBuffer<SoftifyException> {
    override fun read(buf: ByteBuffer): SoftifyException {
        

        return when(buf.getInt()) {
            1 -> SoftifyException.Network(
                FfiConverterString.read(buf),
                )
            2 -> SoftifyException.NotFound(
                FfiConverterString.read(buf),
                )
            3 -> SoftifyException.Decryption(
                FfiConverterString.read(buf),
                )
            4 -> SoftifyException.Database(
                FfiConverterString.read(buf),
                )
            5 -> SoftifyException.QualityVerification(
                FfiConverterString.read(buf),
                )
            6 -> SoftifyException.ProviderUnavailable(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> SoftifyException.Download(
                FfiConverterString.read(buf),
                )
            8 -> SoftifyException.Import(
                FfiConverterString.read(buf),
                )
            9 -> SoftifyException.Scan(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SoftifyException): ULong {
        return when(value) {
            is SoftifyException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.NotFound -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.Decryption -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.Database -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.QualityVerification -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.ProviderUnavailable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`provider`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.Download -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.Import -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SoftifyException.Scan -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SoftifyException, buf: ByteBuffer) {
        when(value) {
            is SoftifyException.Network -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.NotFound -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.Decryption -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.Database -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.QualityVerification -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.ProviderUnavailable -> {
                buf.putInt(6)
                FfiConverterString.write(value.`provider`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.Download -> {
                buf.putInt(7)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.Import -> {
                buf.putInt(8)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SoftifyException.Scan -> {
                buf.putInt(9)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





